    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                nr, nc = r + dr, c + dc
                if color == background or not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                for rr, cc, step_r, step_c in (
                    (r - dr, c - dc, -dr, -dc),
                    (nr + dr, nc + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out
